import{_ as e,o as d,c as r,a2 as o}from"./chunks/framework.DgVVaeR-.js";const u=JSON.parse('{"title":"ソースコード監査・修正記録（2026-09-26）","description":"","frontmatter":{},"headers":[],"relativePath":"dev/audit-2026-09-26.md","filePath":"dev/audit-2026-09-26.md","lastUpdated":1790400774000}'),a={name:"dev/audit-2026-09-26.md"};function i(c,t,l,n,s,h){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="ソースコード監査・修正記録-2026-09-26" tabindex="-1">ソースコード監査・修正記録（2026-09-26） <a class="header-anchor" href="#ソースコード監査・修正記録-2026-09-26" aria-label="Permalink to &quot;ソースコード監査・修正記録（2026-09-26）&quot;">​</a></h1><p><code>git pull --ff-only origin main</code> 後の <code>1d9dfe6</code> を基準に、Android の認証・通信・設定保存・一覧状態・更新処理、および Rust の画像展開・署名検証を調査した。</p><h2 id="確認した問題と修正" tabindex="-1">確認した問題と修正 <a class="header-anchor" href="#確認した問題と修正" aria-label="Permalink to &quot;確認した問題と修正&quot;">​</a></h2><table tabindex="0"><thead><tr><th>優先度</th><th>分類</th><th>問題と影響</th><th>修正</th><th>主な対象</th></tr></thead><tbody><tr><td>高</td><td>セキュリティ</td><td>Pixiv ログインのリダイレクト判定がホスト名の部分一致を含み、想定外の URL を認証結果として扱う。階層構造を持たない URI では例外も起こり得る。</td><td>許可したスキーム・ホスト・ポート・パスを検証し、不正・重複コードを拒否。WebView と Intent で同一のポリシーを使用。</td><td><code>LoginUrlPolicy.kt</code>、<code>LoginScreens.kt</code>、<code>IllustiaAuthFeedModule.kt</code></td></tr><tr><td>高</td><td>セキュリティ</td><td>Discord ログインが URL の部分一致と任意の JavaScript alert をトークン取得に使用する。</td><td>正確な HTTPS オリジンとアプリのパスを検証し、JavaScript 実行結果のコールバックで取得。画面終了時に WebView を破棄。</td><td><code>DiscordLoginScreen.kt</code></td></tr><tr><td>高</td><td>セキュリティ</td><td>PallaSync の Ed25519 検証が弱い公開鍵を受理する。</td><td><code>verify_strict</code> を使用。通常の署名と既存の旧形式との互換性は回帰テストで確認。</td><td><code>rust/pallasync-core/src/crypto.rs</code></td></tr><tr><td>中</td><td>性能・不具合</td><td>アニメーション ZIP のフレームを丸ごとメモリに保持し、無制限に書き込みタスクを生成する。失敗・キャンセル時に一時ファイル削除と書き込みが競合する。</td><td>既存の blocking worker 内で逐次ストリーミングし、一時ディレクトリの所有権を worker に保持。正規化後の重複エントリも拒否。</td><td><code>rust/pixiv-api/src/ugoira.rs</code></td></tr><tr><td>中</td><td>性能・不具合</td><td>キャッシュへの並行追加で容量上限を超える。満杯のキャッシュで既存キーを更新すると無関係な応答も削除され、再通信が増える。</td><td>更新操作を同期化し、既存キーの更新時は不要な退避を行わない。</td><td><code>PixivApiCache.kt</code></td></tr><tr><td>中</td><td>不具合</td><td>HTTP ヘッダー受信後に本文の読み取りが失敗すると、例外がコールバックから漏れて待機中の coroutine に通知されない。</td><td><code>IOException</code> を呼び出し元に返し、応答を確実に閉じる。</td><td><code>OkHttpAwait.kt</code></td></tr><tr><td>中</td><td>不具合</td><td>検索ページ蓄積中のキャンセルを握り潰し、古い検索結果を画面状態に反映する可能性がある。</td><td>キャンセル例外を再送出。</td><td><code>IllustiaAuthFeedModule.kt</code></td></tr><tr><td>中</td><td>不具合</td><td>全体の成人向けフィルターが無効だと、関連作品の表示設定変更が読み込み済み一覧に反映されない。</td><td>関連作品の設定も早期 return の条件に含める。</td><td><code>IllustListExtensions.kt</code></td></tr><tr><td>高</td><td>データ保持</td><td>設定スキーマ更新時に DataStore・Room の値が旧設定の既定値で置換され得る。暗号化ストアを使用できない場合、移行処理が保持すべきトークンも削除する。</td><td>現在の保存先から値を引き継ぎ、移行を中断しても再試行可能な順序で保存。フォールバックの認証情報を保持し、暗号化ストア復旧後に移す。旧コピーの同期削除後に完了とする。</td><td><code>SettingsStoreMigration.kt</code>、<code>SettingsStorePreferences.kt</code></td></tr><tr><td>中</td><td>セキュリティ</td><td>APK 更新ファイルの検証がパス文字列の前方一致のみで、同じ接頭辞を持つ隣接ディレクトリも許可する。</td><td>正規化したパスのディレクトリ境界を検証。</td><td><code>AppUpdaterRepository.kt</code></td></tr><tr><td>高</td><td>開発環境の依存関係</td><td>ドキュメント用の Vite 5 / esbuild、および nanoid に既知の問題が残っている。</td><td>Vite を 6.4.3 に固定し、lockfile を更新。esbuild 0.25.12、nanoid 3.3.19 を解決。</td><td><code>package.json</code>、<code>package-lock.json</code></td></tr><tr><td>高</td><td>ベンチマークの依存関係</td><td>AndroidX Benchmark が取り込む Wire 6.4.0 に Protobuf デコードの問題がある。</td><td>Wire の共通・JVM モジュールに 6.4.5 の制約を追加。</td><td><code>benchmark/build.gradle</code></td></tr><tr><td>高</td><td>静的解析ツールの依存関係</td><td>ビルドスクリプトの修正版固定が独立した <code>ktlint</code> / <code>androidLintTool</code> のクラスパスには届かず、Logback・Bouncy Castle・Commons Lang・HttpClient の古い版が使用される。</td><td>既存のセキュリティ版設定を、該当するツールの構成にも限定して適用。</td><td><code>build.gradle</code>、既存の <code>gradle.properties</code></td></tr></tbody></table><h2 id="検証" tabindex="-1">検証 <a class="header-anchor" href="#検証" aria-label="Permalink to &quot;検証&quot;">​</a></h2><ul><li>Android：<code>:app:testDebugUnitTest</code> 全165件成功（48スイート、失敗・スキップなし）。新規回帰テストでは URL 検証、本文読み取り失敗、キャンセル後の応答破棄、APK パス境界、キャッシュ競合、表示設定反映、設定移行の中断・復旧を確認。</li><li>Kotlin：<code>:app:ktlintMainSourceSetCheck</code>、<code>:app:ktlintTestSourceSetCheck</code>、<code>:app:detekt</code>、<code>:app:checkQualityBaselineBudgets</code> 成功。既存の解析ベースラインは拡張していない。</li><li>Rust Pixiv：<code>cargo test --all-features</code>（40件）、<code>cargo fmt --check</code>、<code>cargo clippy --all-targets --all-features -- -D warnings</code> 成功。</li><li>Rust PallaSync：<code>cargo test</code>（5件）、<code>cargo fmt --check</code> 成功。厳格な clippy は既存の12件の指摘で失敗。既存の <code>collapsible_if</code>、<code>too_many_arguments</code>、<code>needless_borrows_for_generic_args</code> の3カテゴリのみ許可した再検証は成功。</li><li><code>git diff --check</code> 成功。</li><li>ドキュメント：<code>npm ci</code> と <code>npm run docs:build</code> 成功。更新後の npm 監査は脆弱性0件。</li><li>依存関係修正後にも Android 単体テスト・Kotlin 品質チェックが成功。<code>:benchmark:compileBenchmarkReleaseKotlin</code> 成功。<code>dependencyInsight</code> と依存関係レポートで Wire と静的解析ツールの修正版への切り替えを確認。</li><li><code>:app:lintDebug</code> は修正版のツール依存関係で解析・レポート生成まで完了したが、ソースに対する211 errors / 346 warnings / 7 hints で失敗。既存の翻訳不足や Compose 使用法の指摘を含み、この監査で全件の解消は行っていない。依存関係の互換性エラーやメモリ不足による失敗はなかった。</li></ul><h2 id="依存関係の参照情報" tabindex="-1">依存関係の参照情報 <a class="header-anchor" href="#依存関係の参照情報" aria-label="Permalink to &quot;依存関係の参照情報&quot;">​</a></h2><ul><li>Vite：<a href="https://github.com/advisories/GHSA-fx2h-pf6j-xcff" target="_blank" rel="noreferrer">Windows のアクセス制御</a>、<a href="https://github.com/advisories/GHSA-v6wh-96g9-6wx3" target="_blank" rel="noreferrer">UNC パス</a>、<a href="https://github.com/advisories/GHSA-4w7w-66w2-5vf9" target="_blank" rel="noreferrer">ソースマップのパス検証</a>。VitePress 1.6 系を維持し、同梱の Vue プラグインが許容する Vite 6 系の修正版に固定した。</li><li>esbuild：<a href="https://github.com/advisories/GHSA-67mh-4wv8-2f99" target="_blank" rel="noreferrer">開発サーバーのクロスオリジン読み取り</a>。</li><li>nanoid：<a href="https://github.com/advisories/GHSA-2v37-7h3g-55p8" target="_blank" rel="noreferrer">カスタム生成器の停止性</a>。</li><li>Wire：<a href="https://github.com/advisories/GHSA-9rm7-3qhh-h2mc" target="_blank" rel="noreferrer">Protobuf の長さ検証</a>。</li></ul><p>GitHub が報告した14件を依存関係の解決結果と照合した。npm の4件と Wire の1件に加え、残る9件は次の独立したツールの構成に存在していた。ビルドスクリプト側の固定だけでは対処できていなかったため、この PR で適用先を追加した。</p><table tabindex="0"><thead><tr><th>構成</th><th>ライブラリ</th><th>実際の解決結果（修正前 → 修正後）</th><th>アドバイザリ</th></tr></thead><tbody><tr><td><code>androidLintTool</code></td><td>Bouncy Castle</td><td>1.80.2 → 1.85</td><td><a href="https://github.com/advisories/GHSA-qp49-qgx5-5m26" target="_blank" rel="noreferrer">qp49</a>、<a href="https://github.com/advisories/GHSA-9pwp-9qqc-pr26" target="_blank" rel="noreferrer">9pwp</a>、<a href="https://github.com/advisories/GHSA-c3fc-8qff-9hwx" target="_blank" rel="noreferrer">c3fc</a>、<a href="https://github.com/advisories/GHSA-wg6q-6289-32hp" target="_blank" rel="noreferrer">wg6q</a></td></tr><tr><td><code>ktlint</code></td><td>Logback</td><td>1.3.16 → 1.5.34</td><td><a href="https://github.com/advisories/GHSA-jhq6-gfmj-v8fx" target="_blank" rel="noreferrer">jhq6</a>、<a href="https://github.com/advisories/GHSA-p47f-322f-whfh" target="_blank" rel="noreferrer">p47f</a>、<a href="https://github.com/advisories/GHSA-qqpg-mvqg-649v" target="_blank" rel="noreferrer">qqpg</a></td></tr><tr><td><code>androidLintTool</code></td><td>Commons Lang</td><td>3.16.0 → 3.20.0</td><td><a href="https://github.com/advisories/GHSA-j288-q9x7-2f5v" target="_blank" rel="noreferrer">j288</a></td></tr><tr><td><code>androidLintTool</code></td><td>HttpClient</td><td>4.5.6 → 4.5.14</td><td><a href="https://github.com/advisories/GHSA-7r82-7xv7-xcpj" target="_blank" rel="noreferrer">7r82</a></td></tr><tr><td><code>benchmarkReleaseRuntimeClasspath</code></td><td>Wire runtime / JVM</td><td>6.4.0 → 6.4.5</td><td><a href="https://github.com/advisories/GHSA-9rm7-3qhh-h2mc" target="_blank" rel="noreferrer">9rm7</a></td></tr></tbody></table><p>nanoid は追加の npm 監査で検出し、同じ lockfile 更新で修正した。GitHub の既定ブランチ向けアラートは、PR の取り込みと再解析までは残る場合がある。</p><h2 id="検証範囲の限界" tabindex="-1">検証範囲の限界 <a class="header-anchor" href="#検証範囲の限界" aria-label="Permalink to &quot;検証範囲の限界&quot;">​</a></h2><ul><li>接続済みの Android 端末・エミュレーターがないため、実際の Pixiv・Discord ログインと端末上の設定移行は未検証。</li><li><code>:app:assembleDebug</code> は Android NDK が未導入のため <code>buildRustAndroid</code> / <code>buildPallaSyncCoreAndroid</code> で停止。APK 全体の生成は未完了。</li><li>Android Lint の全体チェックと、PallaSync の厳格 clippy は上記の既存指摘が残るため未通過。</li><li>性能改善は不要なバッファ・タスク・キャッシュ削除を除く実装上の改善。端末上のメモリ量や処理時間のベンチマーク数値は測定していない。</li><li>コード調査と回帰テストで確認できた問題を対象とした記録であり、全経路の動的検査や外部サービスの監査ではない。</li></ul>',13)])])}const f=e(a,[["render",i]]);export{u as __pageData,f as default};
